import {index,voxelFromPlane,planePixel,planeAspect,localEdit,history,volumes,autoSeed} from './algorithm.mjs';
import {filesFromDrop,describeInput} from './drop-files.mjs';
import {maxSourceSlices} from './measurement.mjs';
const $=id=>document.getElementById(id),names=['','Intraparenchymal','Intraventricular','Subarachnoid','Subdural','Epidural'],colors=[[0,0,0],[255,78,84],[79,172,255],[255,194,57],[184,109,252],[66,225,166]];
let volume=null,mask=null,edits=null,worker=null,preview=null,holding=null,cross=[0,0,0],availableGroups=[];const canvases=['axial','coronal','sagittal'];
function status(text){$('status').textContent=text;}
function clearVolume(){volume=mask=edits=preview=null;if(holding)clearInterval(holding.timer);holding=null;for(const plane of canvases){const canvas=$(plane);canvas.width=canvas.height=1;canvas.getContext('2d').clearRect(0,0,1,1);}$('volumes').textContent='No volume loaded.';$('warnings').hidden=true;$('warnings').textContent='';}
function setVolume(v){volume=v;mask=new Uint8Array(v.data.length);edits=history(mask);cross=v.dims.map(n=>Math.floor(n/2));for(const [id,dim] of [['x',0],['y',1],['z',2]]){$(id).max=v.dims[dim]-1;$(id).value=cross[dim];}const warnings=v.warnings||[];$('warnings').hidden=!warnings.length;$('warnings').textContent=warnings.join(' ');status((v.synthetic?'Synthetic demo':'CT source grid')+' · '+v.dims.join(' × ')+' · Float32 · local only');draw();}
function synthetic(){const dims=[64,64,32],data=new Float32Array(dims.reduce((a,b)=>a*b,1));for(let z=0;z<dims[2];z++)for(let y=0;y<dims[1];y++)for(let x=0;x<dims[0];x++){
 const r=Math.hypot((x-32)/25,(y-32)/26,(z-16)/13),lesion=Math.hypot((x-26)/7,(y-30)/5,(z-17)/5);data[index(dims,x,y,z)]=r>1?-950:lesion<1?68:r>.88?350:27+4*Math.sin(x*.27+y*.18+z*.43);
 }setVolume({dims,data,matrix:[.8,0,0,0,.8,0,0,0,1.5],origin:[0,0,0],synthetic:true});}
function draw(){if(!volume)return;const previewSet=preview?new Set(preview):null;for(const plane of canvases){const canvas=$(plane),dims=volume.dims,w=plane==='sagittal'?dims[1]:dims[0],h=plane==='axial'?dims[1]:dims[2],ctx=canvas.getContext('2d');canvas.width=w;canvas.height=h;canvas.style.aspectRatio=String(planeAspect(volume,plane));const image=ctx.createImageData(w,h),level=Number($('level').value)||60,width=Math.max(1,Number($('width').value)||160),selected=Number($('label').value);
 for(let b=0;b<h;b++)for(let a=0;a<w;a++){const xyz=voxelFromPlane(plane,a,b,cross[plane==='axial'?2:plane==='coronal'?1:0]),i=index(dims,...xyz),out=(b*w+a)*4,hu=volume.data[i],gray=Number.isFinite(hu)?Math.round(Math.max(0,Math.min(255,255*(hu-(level-width/2))/width))):0,lab=previewSet?.has(i)?(holding?.tool==='shrink'?0:selected):mask[i],c=colors[lab];image.data[out]=lab?Math.round(gray*.48+c[0]*.52):gray;image.data[out+1]=lab?Math.round(gray*.48+c[1]*.52):gray;image.data[out+2]=lab?Math.round(gray*.48+c[2]*.52):gray;image.data[out+3]=255;}
 ctx.putImageData(image,0,0);const [cx,cy]=planePixel(plane,cross);ctx.strokeStyle='#30f2d6';ctx.lineWidth=Math.max(1,w/130);ctx.beginPath();ctx.moveTo(cx+.5,0);ctx.lineTo(cx+.5,h);ctx.moveTo(0,cy+.5);ctx.lineTo(w,cy+.5);ctx.stroke();}
 const m=volumes(mask,volume);$('volumes').replaceChildren(...names.slice(1).map((name,n)=>{const span=document.createElement('span');span.style.color=`rgb(${colors[n+1].join(',')})`;span.textContent=name+': '+(m[n+1]||0).toFixed(3);return span;}));const total=document.createElement('strong');total.textContent='Total: '+m.total.toFixed(3);$('volumes').append(total);
}
function point(e,plane){const rect=e.currentTarget.getBoundingClientRect(),a=Math.max(0,Math.min(e.currentTarget.width-1,Math.floor((e.clientX-rect.left)*e.currentTarget.width/rect.width))),b=Math.max(0,Math.min(e.currentTarget.height-1,Math.floor((e.clientY-rect.top)*e.currentTarget.height/rect.height)));return voxelFromPlane(plane,a,b,cross[plane==='axial'?2:plane==='coronal'?1:0]);}
function updatePreview(){if(!holding||!volume)return;const elapsed=(performance.now()-holding.start)/800,radius=Number($('radius').value)+Math.min(24,elapsed*2);preview=localEdit(volume,mask,holding.xyz,holding.label,holding.tool,radius,1);draw();}
for(const plane of canvases){const c=$(plane);c.addEventListener('contextmenu',e=>e.preventDefault());c.addEventListener('pointerdown',e=>{if(!volume)return;e.preventDefault();const xyz=point(e,plane);cross=xyz;for(const [id,i] of [['x',0],['y',1],['z',2]])$(id).value=cross[i];const tool=$('tool').value,label=Number($('label').value);if(e.button===2||e.shiftKey){draw();return;}if(tool==='seed'){const hits=autoSeed(volume,xyz);if(hits.length>200000){status('Seed over 200,000 voxels; refine input or choose another location.');draw();return;}edits.commit(hits.filter(i=>mask[i]===0),label);status('Seed: '+hits.length+' connected voxels');draw();return;}holding={xyz,tool,label,start:performance.now(),pointer:e.pointerId};c.setPointerCapture(e.pointerId);updatePreview();holding.timer=setInterval(updatePreview,150);});c.addEventListener('pointerup',e=>{if(!holding)return;clearInterval(holding.timer);updatePreview();const changes=preview||[];edits.commit(changes,holding.tool==='grow'?holding.label:0);holding=null;preview=null;status('Local edit: '+changes.length+' source voxels');draw();});c.addEventListener('pointercancel',()=>{if(holding)clearInterval(holding.timer);holding=null;preview=null;draw();});}
for(const [id,dim] of [['x',0],['y',1],['z',2]])$(id).addEventListener('input',e=>{cross[dim]=Number(e.target.value);draw();});
for(const id of ['level','width','label'])$(id).addEventListener('input',draw);$('radius').addEventListener('input',()=>{$('radiusText').textContent=$('radius').value+' mm';updatePreview();});$('undo').onclick=()=>{if(edits?.undo())draw();};$('redo').onclick=()=>{if(edits?.redo())draw();};$('demo').onclick=synthetic;
function configureRange(){const g=availableGroups.find(q=>q.key===$('series').value);if(!g)return;const depth=g.measurementDepth??g.frames,max=maxSourceSlices([g.dims[0],g.dims[1],depth]),required=depth>max;$('sliceRange').hidden=!required;$('rangeStart').value=$('rangeEnd').value='';$('rangeStart').max=$('rangeEnd').max=depth-1;$('rangeHint').textContent=required?`Исходная серия ${g.frames} срезов${depth!==g.frames?`, после исключения стыка — ${depth}`:''}; индексы 0–${depth-1}, максимум ${max} подряд без изменения разрешения. Выбери область головы и проверь её в трёх проекциях. Можно выбрать другой диапазон; текущая маска при этом сбросится.`:'';}
$('series').onchange=configureRange;
function scan(files,isDirectory=false){if(!files.length)return;clearVolume();worker?.terminate();worker=new Worker('./io-worker.js?v=0.1.4');const current=worker,input=describeInput(files,isDirectory);status('Сканирование · '+input);availableGroups=[];$('series').hidden=$('load').hidden=$('sliceRange').hidden=true;worker.onerror=e=>status('Worker failure ('+input+'): '+e.message);worker.onmessage=({data})=>{if(worker!==current)return;if(data.type==='error'){status('Measurement blocked [v0.1.4; '+input+']: '+data.message);return;}if(data.type==='groups'){availableGroups=data.groups;const select=$('series');select.replaceChildren(...data.groups.map(g=>{const o=document.createElement('option');o.value=g.key;o.textContent=g.name+' · '+g.modality+' · '+g.frames+' slices · '+g.dims.join('×');return o;}));select.hidden=$('load').hidden=false;configureRange();status('Choose a series ('+data.groups.length+' found; '+data.skipped+' skipped).');}if(data.type==='volume')setVolume(data.volume);if(data.type==='progress')status(data.text+' '+Math.round(data.fraction*100)+'%');};worker.postMessage({type:'scan',slot:'ct',files:Array.from(files)});}
$('files').onchange=e=>scan(e.target.files);$('folder').onchange=e=>scan(e.target.files,true);$('load').onclick=()=>{if(!worker)return;let sliceRange=null;if(!$('sliceRange').hidden){const start=Number($('rangeStart').value),end=Number($('rangeEnd').value),g=availableGroups.find(q=>q.key===$('series').value);if(!$('rangeStart').value||!$('rangeEnd').value||!Number.isInteger(start)||!Number.isInteger(end)||start<0||end>=(g.measurementDepth??g.frames)||end-start<1||end-start+1>maxSourceSlices(g.dims)){status('Укажи корректный непрерывный диапазон срезов в пределах лимита.');return;}sliceRange=[start,end];}clearVolume();status('Decoding source CT…');worker.postMessage({type:'build',key:$('series').value,sliceRange});};
document.addEventListener('dragover',e=>e.preventDefault());
document.addEventListener('drop',async e=>{
 e.preventDefault();
 try{const isDirectory=Array.from(e.dataTransfer.items||[]).some(item=>item.webkitGetAsEntry?.()?.isDirectory);scan(await filesFromDrop(e.dataTransfer),isDirectory);}
 catch(error){status('Не удалось прочитать перетащенную папку: '+error.message);}
});
